package com.securelib.crypto

import java.security.SecureRandom
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.ConcurrentLinkedQueue
import java.util.concurrent.atomic.AtomicInteger
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec

data class CryptoConnection(
    val id: Int,
    val cipher: Cipher,
    val keySpec: SecretKeySpec,
    val nonceState: NonceState
)

class NonceState(
    private val baseNonce: ByteArray,
    private val counter: AtomicInteger = AtomicInteger(0)
) {
    private val random = SecureRandom()

    fun nextNonce(): ByteArray {
        val nonce = ByteArray(12)
        val count = counter.getAndIncrement()
        // XOR counter into base nonce for uniqueness
        System.arraycopy(baseNonce, 0, nonce, 0, 12)
        nonce[8] = (count shr 24 and 0xFF).toByte()
        nonce[9] = (count shr 16 and 0xFF).toByte()
        nonce[10] = (count shr 8 and 0xFF).toByte()
        nonce[11] = (count and 0xFF).toByte()
        return nonce
    }

    fun reset() {
        counter.set(0)
    }
}

class CryptoConnectionPool(
    private val poolSize: Int = 8,
    private val masterKey: ByteArray
) {
    private val pool = ConcurrentLinkedQueue<CryptoConnection>()
    private val connectionCounter = AtomicInteger(0)
    private val derivedKeys = ConcurrentHashMap<Int, SecretKeySpec>()
    private val random = SecureRandom()

    init {
        require(masterKey.size == 32) { "Master key must be 256 bits" }
        for (i in 0 until poolSize) {
            pool.offer(createConnection())
        }
    }

    private fun deriveKey(connectionId: Int): SecretKeySpec {
        return derivedKeys.computeIfAbsent(connectionId) { id ->
            val derivationInput = ByteArray(32 + 4)
            System.arraycopy(masterKey, 0, derivationInput, 0, 32)
            derivationInput[32] = (id shr 24 and 0xFF).toByte()
            derivationInput[33] = (id shr 16 and 0xFF).toByte()
            derivationInput[34] = (id shr 8 and 0xFF).toByte()
            derivationInput[35] = (id and 0xFF).toByte()
            val digest = java.security.MessageDigest.getInstance("SHA-256")
            val derived = digest.digest(derivationInput)
            SecretKeySpec(derived, "AES")
        }
    }

    private fun createConnection(): CryptoConnection {
        val id = connectionCounter.getAndIncrement()
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = deriveKey(id)
        val baseNonce = ByteArray(12)
        random.nextBytes(baseNonce)
        return CryptoConnection(id, cipher, keySpec, NonceState(baseNonce))
    }

    fun acquire(): CryptoConnection {
        return pool.poll() ?: createConnection()
    }

    fun release(connection: CryptoConnection) {
        connection.nonceState.reset()
        if (pool.size < poolSize) {
            pool.offer(connection)
        }
    }

    fun encrypt(plaintext: ByteArray, aad: ByteArray = ByteArray(0)): EncryptedPayload {
        val conn = acquire()
        try {
            val nonce = conn.nonceState.nextNonce()
            val gcmSpec = GCMParameterSpec(128, nonce)
            conn.cipher.init(Cipher.ENCRYPT_MODE, conn.keySpec, gcmSpec)
            conn.cipher.updateAAD(aad)
            val ciphertext = conn.cipher.doFinal(plaintext)
            return EncryptedPayload(
                connectionId = conn.id,
                nonce = nonce,
                ciphertext = ciphertext,
                aad = aad
            )
        } finally {
            release(conn)
        }
    }

    fun decrypt(payload: EncryptedPayload): ByteArray {
        val conn = acquire()
        try {
            val keySpec = deriveKey(payload.connectionId)
            val gcmSpec = GCMParameterSpec(128, payload.nonce)
            conn.cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
            conn.cipher.updateAAD(payload.aad)
            return conn.cipher.doFinal(payload.ciphertext)
        } finally {
            release(conn)
        }
    }
}

data class EncryptedPayload(
    val connectionId: Int,
    val nonce: ByteArray,
    val ciphertext: ByteArray,
    val aad: ByteArray
)

fun main() {
    val masterKey = ByteArray(32).also { SecureRandom().nextBytes(it) }
    val pool = CryptoConnectionPool(poolSize = 4, masterKey = masterKey)

    val message1 = "Transfer 1000 to account A".toByteArray()
    val message2 = "Transfer 5000 to account B".toByteArray()

    val encrypted1 = pool.encrypt(message1, "transaction".toByteArray())
    val encrypted2 = pool.encrypt(message2, "transaction".toByteArray())

    val decrypted1 = pool.decrypt(encrypted1)
    val decrypted2 = pool.decrypt(encrypted2)

    println("Decrypted 1: ${String(decrypted1)}")
    println("Decrypted 2: ${String(decrypted2)}")
}
